// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlaqsy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 11', function test( t ) {
	t.strictEqual( dlaqsy.length, 11, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid matrix triangle', function test( t ) {
	var values;
	var A;
	var S;
	var i;

	A = new Float64Array( 9 );
	S = new Float64Array( 3 );

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		'all',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlaqsy( value, 3, A, 3, 1, 0, S, 1, 0, 0.05, 9.0 );
		};
	}
});

tape( 'the function throws an error if provided a second argument which is a negative integer', function test( t ) {
	var values;
	var A;
	var S;
	var i;

	A = new Float64Array( 9 );
	S = new Float64Array( 3 );

	values = [
		-1,
		-2,
		-3
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlaqsy( 'upper', value, A, 3, 1, 0, S, 1, 0, 0.05, 9.0 );
		};
	}
});

tape( 'the function equilibrates a symmetric matrix (row-major, upper)', function test( t ) {
	var expected;
	var equed;
	var data;
	var A;
	var S;

	data = ROW_MAJOR_UPPER;

	A = new Float64Array( data.A );
	S = new Float64Array( data.S );

	equed = dlaqsy( data.uplo, data.N, A, data.strideA1, data.strideA2, data.offsetA, S, data.strideS, data.offsetS, data.scond, data.amax );
	expected = new Float64Array( data.A_out );

	t.strictEqual( equed, data.equed, 'returns expected value' );
	t.deepEqual( A, expected, 'returns expected value' );
	t.end();
});

