tape( 'the function returns `N` and leaves the input matrix unchanged if `N` is equal to zero', function test( t ) {
	var expected;
	var equed;
	var A;
	var S;

	A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	S = new Float64Array( [ 0.1, 10.0 ] );
	expected = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );

	equed = dlaqsy( 'upper', 0, A, 2, 1, 0, S, 1, 0, 0.01, 4.0 );
	t.strictEqual( equed, 'N', 'returns expected value' );
	t.deepEqual( A, expected, 'returns expected value' );
	t.end();
});
